import 'package:flutter/material.dart';import '../services/progress_store.dart';import '../widgets/ui.dart';import 'home_screen.dart';
class SplashScreen extends StatefulWidget{final ProgressStore store;const SplashScreen({super.key,required this.store});@override State<SplashScreen> createState()=>_S();}
class _S extends State<SplashScreen> with SingleTickerProviderStateMixin{late AnimationController c;@override void initState(){super.initState();c=AnimationController(vsync:this,duration:const Duration(milliseconds:1000))..forward();Future.delayed(const Duration(milliseconds:1400),(){if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>HomeScreen(store:widget.store)));});}@override void dispose(){c.dispose();super.dispose();}
 @override Widget build(BuildContext x)=>Scaffold(body:Center(child:ScaleTransition(scale:Tween<double>(begin:.6,end:1).animate(CurvedAnimation(parent:c,curve:Curves.elasticOut)),child:Column(mainAxisSize:MainAxisSize.min,children:[Container(width:110,height:110,decoration:BoxDecoration(shape:BoxShape.circle,border:Border.all(color:cyan,width:4),boxShadow:[BoxShadow(color:cyan.withOpacity(.3),blurRadius:30)]),child:const Icon(Icons.flip_camera_android_rounded,color:cyan,size:55)),const SizedBox(height:24),const NeonTitle('GRAVIX',size:44),const Text('CORE ESCAPE',style:TextStyle(color:orange,fontWeight:FontWeight.w900,letterSpacing:4))]))));}
